const tasks = [
  ["early_logs", () => tools.mcp__atira__run_logs({run_id:"run_3c3568bb65f5871e", from:"00:00", to:"11:30", grep:"\\[extract|nothing usable|VALIDATOR|Investig|questions|no material|filed|failed", limit:200})],
  ["erp_inputs", () => tools.mcp__atira__run_inputs({run_id:"run_3c3568bb65f5871e", browser:3, limit:200})],
  ["submit_inputs", () => tools.mcp__atira__run_inputs({run_id:"run_3c3568bb65f5871e", browser:1, from:"10:00", to:"18:30", limit:200})],
  ["artifacts", () => tools.mcp__codex_app__list_artifacts({})]
];
const results = await Promise.allSettled(tasks.map(async ([n,f])=>[n,await f()]));
for (const r of results) text(r.status==="fulfilled" ? `## ${r.value[0]}\n${JSON.stringify(r.value[1])}` : String(r.reason));

const tasks = [
  ["extract_summary", () => tools.mcp__atira__run_logs({run_id:"run_3c3568bb65f5871e", grep:"\\[extract|OPEN QUESTIONS|VALIDATOR|Investigation took|Submission:", limit:100})],
  ["final_flow", () => tools.mcp__atira__run_logs({run_id:"run_3c3568bb65f5871e", from:"10:50", to:"18:32", stream:"stdout,stderr", limit:100})],
  ["screen_initial_form", () => tools.mcp__atira__run_screenshot({run_id:"run_3c3568bb65f5871e", at:"11:35", browser:1})],
  ["screen_final", () => tools.mcp__atira__run_screenshot({run_id:"run_3c3568bb65f5871e", at:"18:23", browser:1})]
];
const rs = await Promise.allSettled(tasks.map(async ([n,f])=>[n,await f()]));
for (const r of rs) {
 if (r.status!=="fulfilled") {text(String(r.reason));continue;}
 const [n,res]=r.value;
 text(`## ${n}`);
 if(res?.content) for(const b of res.content) { if(b.type==="image") image(b); else if(b.type==="text") text(b.text); else text(JSON.stringify(b)); }
 else text(JSON.stringify(res));
}

